--
-- Create or alter function [wf].[wf_try_task_result_code]
--
GO
PRINT (N'Create or alter function [wf].[wf_try_task_result_code]')
GO

CREATE OR ALTER FUNCTION wf.wf_try_task_result_code(@workflow_instance_id BIGINT, @node_key NVARCHAR(128))
RETURNS INT
AS
BEGIN
    DECLARE @r INT;
    SELECT TOP (1) @r = ne.result_code
    FROM wf.node_execution AS ne
    INNER JOIN wf.workflow_node AS wn ON wn.id = ne.workflow_node_id
    WHERE ne.workflow_instance_id = @workflow_instance_id
      AND wn.node_key = @node_key
      AND ne.status = N'SUCCEEDED'
    ORDER BY ne.ended_at_utc DESC, ne.id DESC;
    RETURN @r;
END;
GO

--
-- Create or alter procedure [wf].[wf_while_continue]
--
GO
PRINT (N'Create or alter procedure [wf].[wf_while_continue]')
GO

CREATE OR ALTER PROCEDURE wf.wf_while_continue
    @while_execution_id BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @workflow_instance_id BIGINT;
    DECLARE @inst BIGINT;
    DECLARE @ctl BIGINT;
    SELECT @inst = workflow_instance_id, @ctl = workflow_node_id FROM wf.node_execution WHERE id = @while_execution_id;

    DECLARE @wcref NVARCHAR(128);
    SELECT @wcref = condition_ref_node_key FROM wf.workflow_node WHERE id = @ctl;

    DECLARE @wcond INT = wf.wf_try_task_result_code(@workflow_instance_id, @wcref);

    IF @wcond IS NULL OR @wcond = 0
    BEGIN
        UPDATE wf.node_execution SET status = N'SUCCEEDED', ended_at_utc = SYSUTCDATETIME() WHERE id = @while_execution_id;
        EXEC wf.wf_engine_on_composite_complete @node_execution_id = @while_execution_id;
        RETURN;
    END

    DECLARE @iter INT = ISNULL((SELECT MAX(iteration_no) FROM wf.node_execution WHERE parent_node_execution_id = @while_execution_id AND workflow_node_id = (
        SELECT TOP (1) child_node_id FROM wf.workflow_edge WHERE parent_node_id = @ctl AND branch_kind = N'BODY' ORDER BY child_order ASC
    )), 0);

    DECLARE @wbody BIGINT;
    SELECT TOP (1) @wbody = child_node_id FROM wf.workflow_edge WHERE parent_node_id = @ctl AND branch_kind = N'BODY' ORDER BY child_order ASC;

    DECLARE @iter1 INT = @iter + 1;
    EXEC wf.wf_engine_activate
        @workflow_instance_id = @inst,
        @workflow_node_id = @wbody,
        @parent_node_execution_id = @while_execution_id,
        @iteration_no = @iter1,
        @sequence_index = NULL,
        @parallel_index = NULL;
END;
GO

--
-- Create or alter function [wf].[wf_try_task_output_json]
--
GO
PRINT (N'Create or alter function [wf].[wf_try_task_output_json]')
GO

CREATE OR ALTER FUNCTION wf.wf_try_task_output_json(@workflow_instance_id BIGINT, @node_key NVARCHAR(128), @jsonPath NVARCHAR(4000))
RETURNS NVARCHAR(MAX)
AS
BEGIN
    DECLARE @out NVARCHAR(MAX);
    SELECT TOP (1) @out = CAST(ne.output_json AS NVARCHAR(MAX))
    FROM wf.node_execution AS ne
    INNER JOIN wf.workflow_node AS wn ON wn.id = ne.workflow_node_id
    WHERE ne.workflow_instance_id = @workflow_instance_id
      AND wn.node_key = @node_key
      AND ne.status = N'SUCCEEDED'
    ORDER BY ne.ended_at_utc DESC, ne.id DESC;

    IF @out IS NULL RETURN NULL;

    IF @jsonPath IS NULL OR LTRIM(RTRIM(@jsonPath)) = N'' RETURN @out;

    IF LEFT(@jsonPath, 1) <> N'$' SET @jsonPath = N'$.' + @jsonPath;

    DECLARE @jq NVARCHAR(MAX) = JSON_QUERY(@out, @jsonPath);
    IF @jq IS NOT NULL RETURN @jq;

    DECLARE @jv NVARCHAR(MAX) = JSON_VALUE(@out, @jsonPath);
    IF @jv IS NULL RETURN NULL;

    DECLARE @bi BIGINT = TRY_CONVERT(BIGINT, @jv);
    IF @bi IS NOT NULL AND CAST(@bi AS NVARCHAR(50)) = LTRIM(RTRIM(@jv))
        RETURN CAST(@bi AS NVARCHAR(50));

    RETURN wf.wf_json_fragment_from_string(@jv);
END;
GO

--
-- Create or alter procedure [wf].[wf_sequence_continue]
--
GO
PRINT (N'Create or alter procedure [wf].[wf_sequence_continue]')
GO

CREATE OR ALTER PROCEDURE wf.wf_sequence_continue
    @sequence_execution_id BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @inst BIGINT;
    DECLARE @seq_node BIGINT;
    SELECT @inst = workflow_instance_id, @seq_node = workflow_node_id FROM wf.node_execution WHERE id = @sequence_execution_id;

    IF NOT EXISTS (
        SELECT 1 FROM wf.workflow_instance
        WHERE id = @inst AND status = N'RUNNING'
    )
        RETURN;

    DECLARE @last_child_ne BIGINT;
    SELECT TOP (1) @last_child_ne = ne.id
    FROM wf.node_execution AS ne
    WHERE ne.parent_node_execution_id = @sequence_execution_id AND ne.status IN (N'SUCCEEDED', N'FAILED', N'SKIPPED')
    ORDER BY ne.ended_at_utc DESC, ne.id DESC;

    DECLARE @last_status VARCHAR(32);
    DECLARE @last_child_wn BIGINT;
    SELECT @last_child_wn = workflow_node_id, @last_status = status FROM wf.node_execution WHERE id = @last_child_ne;

    IF @last_status = N'FAILED'
    BEGIN
        UPDATE wf.node_execution SET status = N'FAILED', ended_at_utc = SYSUTCDATETIME() WHERE id = @sequence_execution_id;
        UPDATE wf.workflow_instance SET status = N'FAILED', completed_at_utc = SYSUTCDATETIME() WHERE id = @inst AND status = N'RUNNING';
        RETURN;
    END

    DECLARE @next_order INT;
    SELECT @next_order = e.child_order + 1
    FROM wf.workflow_edge AS e
    WHERE e.parent_node_id = @seq_node AND e.child_node_id = @last_child_wn;

    DECLARE @next_child BIGINT;
    SELECT TOP (1) @next_child = child_node_id
    FROM wf.workflow_edge
    WHERE parent_node_id = @seq_node AND child_order = @next_order;

    IF @next_child IS NULL
    BEGIN
        UPDATE wf.node_execution SET status = N'SUCCEEDED', ended_at_utc = SYSUTCDATETIME() WHERE id = @sequence_execution_id;
        EXEC wf.wf_engine_on_composite_complete @node_execution_id = @sequence_execution_id;
        RETURN;
    END;

    DECLARE @iter INT = (SELECT iteration_no FROM wf.node_execution WHERE id = @sequence_execution_id);
    EXEC wf.wf_engine_activate
        @workflow_instance_id = @inst,
        @workflow_node_id = @next_child,
        @parent_node_execution_id = @sequence_execution_id,
        @iteration_no = @iter,
        @sequence_index = @next_order,
        @parallel_index = NULL;
END;
GO

--
-- Create or alter procedure [wf].[wf_parallel_continue]
--
GO
PRINT (N'Create or alter procedure [wf].[wf_parallel_continue]')
GO

CREATE OR ALTER PROCEDURE wf.wf_parallel_continue
    @parallel_execution_id BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @inst BIGINT;
    DECLARE @pnode BIGINT;
    SELECT @inst = workflow_instance_id, @pnode = workflow_node_id FROM wf.node_execution WHERE id = @parallel_execution_id;

    IF NOT EXISTS (
        SELECT 1 FROM wf.workflow_instance
        WHERE id = @inst AND status = N'RUNNING'
    )
        RETURN;

    DECLARE @total INT = (SELECT COUNT(*) FROM wf.workflow_edge WHERE parent_node_id = @pnode);

    DECLARE @finished INT = (
        SELECT COUNT(*)
        FROM wf.node_execution AS ne
        WHERE ne.parent_node_execution_id = @parallel_execution_id
          AND ne.status IN (N'SUCCEEDED', N'FAILED', N'SKIPPED', N'CANCELLED')
    );

    IF @finished < @total RETURN;

    IF EXISTS (
        SELECT 1 FROM wf.node_execution
        WHERE parent_node_execution_id = @parallel_execution_id AND status = N'FAILED'
    )
    BEGIN
        UPDATE wf.node_execution SET status = N'FAILED', ended_at_utc = SYSUTCDATETIME() WHERE id = @parallel_execution_id;
        UPDATE wf.workflow_instance SET status = N'FAILED', completed_at_utc = SYSUTCDATETIME() WHERE id = @inst AND status = N'RUNNING';
        RETURN;
    END

    UPDATE wf.node_execution SET status = N'SUCCEEDED', ended_at_utc = SYSUTCDATETIME() WHERE id = @parallel_execution_id;
    EXEC wf.wf_engine_on_composite_complete @node_execution_id = @parallel_execution_id;
END;
GO

--
-- Create or alter procedure [wf].[wf_engine_on_composite_complete]
--
GO
PRINT (N'Create or alter procedure [wf].[wf_engine_on_composite_complete]')
GO

CREATE OR ALTER PROCEDURE wf.wf_engine_on_composite_complete
    @node_execution_id BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @parent BIGINT;
    DECLARE @inst BIGINT;
    SELECT @parent = parent_node_execution_id, @inst = workflow_instance_id FROM wf.node_execution WHERE id = @node_execution_id;

    IF @parent IS NULL
    BEGIN
        UPDATE wf.workflow_instance
        SET status = N'COMPLETED', completed_at_utc = SYSUTCDATETIME()
        WHERE id = @inst AND status = N'RUNNING';
        RETURN;
    END

    EXEC wf.wf_engine_continue_parent @parent_node_execution_id = @parent;
END;
GO

--
-- Create or alter procedure [wf].[wf_engine_continue_parent]
--
GO
PRINT (N'Create or alter procedure [wf].[wf_engine_continue_parent]')
GO

CREATE OR ALTER PROCEDURE wf.wf_engine_continue_parent
    @parent_node_execution_id BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @pnode BIGINT;
    DECLARE @ptype VARCHAR(32);
    SELECT @pnode = ne.workflow_node_id, @ptype = wn.node_type
    FROM wf.node_execution AS ne
    INNER JOIN wf.workflow_node AS wn ON wn.id = ne.workflow_node_id
    WHERE ne.id = @parent_node_execution_id;

    IF @ptype = N'SEQUENCE'
        EXEC wf.wf_sequence_continue @sequence_execution_id = @parent_node_execution_id;

    ELSE IF @ptype = N'PARALLEL'
        EXEC wf.wf_parallel_continue @parallel_execution_id = @parent_node_execution_id;

    ELSE IF @ptype IN (N'IF', N'SWITCH')
    BEGIN
        UPDATE wf.node_execution SET status = N'SUCCEEDED', ended_at_utc = SYSUTCDATETIME() WHERE id = @parent_node_execution_id;
        EXEC wf.wf_engine_on_composite_complete @node_execution_id = @parent_node_execution_id;
    END

    ELSE IF @ptype = N'REPEAT'
        EXEC wf.wf_repeat_continue @repeat_execution_id = @parent_node_execution_id;

    ELSE IF @ptype = N'WHILE'
        EXEC wf.wf_while_continue @while_execution_id = @parent_node_execution_id;

    /* FOREACH arrives with wf_sql_foreach_support.sql; dispatch through the router so
       re-running this base script never drops FOREACH continuation. */
    ELSE IF @ptype = N'FOREACH'
        EXEC wf.wf_foreach_route_continue @foreach_execution_id = @parent_node_execution_id;
END;
GO

