--
-- Create or alter procedure [wf].[wf_engine_on_action_complete]
--
GO
PRINT (N'Create or alter procedure [wf].[wf_engine_on_action_complete]')
GO

CREATE OR ALTER PROCEDURE wf.wf_engine_on_action_complete
    @action_execution_id BIGINT,
    @result_code INT,
    @output_json NVARCHAR(MAX) NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @inst BIGINT;
    DECLARE @wn BIGINT;
    DECLARE @parent BIGINT;
    /* Normalize payload as NVARCHAR only. Do not use a typed `json` variable here: assigning `json`
       to an `nvarchar(max)` column (older schemas) raises error 257; `nvarchar` assigns to both
       `nvarchar(max)` and native `json` columns via implicit conversion where supported. */
    DECLARE @oj NVARCHAR(MAX) = CASE
        WHEN @output_json IS NULL THEN NULL
        WHEN LTRIM(RTRIM(@output_json)) = N'' THEN NULL
        ELSE @output_json
    END;

    SELECT @inst = workflow_instance_id, @wn = workflow_node_id, @parent = parent_node_execution_id
    FROM wf.node_execution WHERE id = @action_execution_id;

    IF @result_code < 0
    BEGIN
        UPDATE wf.node_execution
        SET status = N'FAILED',
            result_code = @result_code,
            output_json = @oj,
            ended_at_utc = SYSUTCDATETIME(),
            engine_error_code = @result_code
        WHERE id = @action_execution_id;

        DELETE FROM wf.task_lease WHERE node_execution_id = @action_execution_id;

        -- Leave instance RUNNING so sibling FOREACH tasks remain claimable.
        RETURN;
    END

    UPDATE wf.node_execution
    SET status = N'SUCCEEDED',
        result_code = @result_code,
        output_json = @oj,
        ended_at_utc = SYSUTCDATETIME()
    WHERE id = @action_execution_id;

    DELETE FROM wf.task_lease WHERE node_execution_id = @action_execution_id;

    -- Bind action outputs into FOREACH/sample scope (qcPass, qcPath, …).
    EXEC wf.wf_apply_output_bindings
        @action_execution_id = @action_execution_id,
        @result_code = @result_code,
        @output_json = @oj;

    IF NOT EXISTS (
        SELECT 1 FROM wf.workflow_instance
        WHERE id = @inst AND status = N'RUNNING'
    )
        RETURN;

    IF @parent IS NULL
    BEGIN
        UPDATE wf.workflow_instance
        SET status = N'COMPLETED', completed_at_utc = SYSUTCDATETIME()
        WHERE id = @inst AND status = N'RUNNING';
        RETURN;
    END

    DECLARE @ptype VARCHAR(32);
    SELECT @ptype = wn.node_type
    FROM wf.node_execution AS ne
    INNER JOIN wf.workflow_node AS wn ON wn.id = ne.workflow_node_id
    WHERE ne.id = @parent;

    IF @ptype = N'SEQUENCE'
        EXEC wf.wf_sequence_continue @sequence_execution_id = @parent;

    ELSE IF @ptype = N'PARALLEL'
        EXEC wf.wf_parallel_continue @parallel_execution_id = @parent;

    ELSE IF @ptype IN (N'IF', N'SWITCH')
    BEGIN
        UPDATE wf.node_execution SET status = N'SUCCEEDED', ended_at_utc = SYSUTCDATETIME() WHERE id = @parent;
        EXEC wf.wf_engine_on_composite_complete @node_execution_id = @parent;
    END

    ELSE IF @ptype = N'REPEAT'
        EXEC wf.wf_repeat_continue @repeat_execution_id = @parent;

    ELSE IF @ptype = N'WHILE'
        EXEC wf.wf_while_continue @while_execution_id = @parent;

    /* FOREACH arrives with wf_sql_foreach_support.sql; dispatch through the router so
       re-running this base script never drops FOREACH continuation. */
    ELSE IF @ptype = N'FOREACH'
        EXEC wf.wf_foreach_route_continue @foreach_execution_id = @parent;
END;
GO

--
-- Create or alter procedure [wf].[sp_worker_submit_result]
--
GO
PRINT (N'Create or alter procedure [wf].[sp_worker_submit_result]')
GO

CREATE OR ALTER PROCEDURE wf.sp_worker_submit_result
    @node_execution_id BIGINT,
    @worker_id BIGINT,
    @worker_token NVARCHAR(4000),
    @result_code INT,
    @output_json NVARCHAR(MAX) NULL,
    @accepted BIT OUTPUT,
    @instance_status VARCHAR(32) OUTPUT,
    @next_ready_count INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @accepted = 0;
    SET @next_ready_count = 0;
    SET @instance_status = NULL;

    EXEC wf.wf_worker_authenticate @worker_id = @worker_id, @worker_token = @worker_token;

    BEGIN TRANSACTION;

    DECLARE @lease_worker BIGINT;
    SELECT @lease_worker = worker_id FROM wf.task_lease WITH (UPDLOCK, HOLDLOCK) WHERE node_execution_id = @node_execution_id;

    IF @lease_worker IS NULL OR @lease_worker <> @worker_id
    BEGIN
        ROLLBACK TRANSACTION;
        RETURN;
    END

    DECLARE @cur_status VARCHAR(32);
    SELECT @cur_status = status FROM wf.node_execution WITH (UPDLOCK, HOLDLOCK) WHERE id = @node_execution_id;

    IF @cur_status <> N'RUNNING'
    BEGIN
        ROLLBACK TRANSACTION;
        RETURN;
    END

    DECLARE @output_json_text NVARCHAR(MAX) = CASE
        WHEN @output_json IS NULL THEN NULL
        ELSE CONVERT(NVARCHAR(MAX), @output_json)
    END;

    EXEC wf.wf_engine_on_action_complete
        @action_execution_id = @node_execution_id,
        @result_code = @result_code,
        @output_json = @output_json_text;

    SET @accepted = 1;

    SELECT @instance_status = status FROM wf.workflow_instance WHERE id = (SELECT workflow_instance_id FROM wf.node_execution WHERE id = @node_execution_id);

    SELECT @next_ready_count = COUNT(*)
    FROM wf.node_execution
    WHERE workflow_instance_id = (SELECT workflow_instance_id FROM wf.node_execution WHERE id = @node_execution_id)
      AND status = N'READY';

    COMMIT TRANSACTION;
END;
GO

--
-- Create or alter procedure [wf].[sp_worker_request_task]
--
GO
PRINT (N'Create or alter procedure [wf].[sp_worker_request_task]')
GO

-- Native json parameters (parity with PG jsonb). Recreate if prior NVARCHAR form exists.
IF OBJECT_ID(N'wf.sp_worker_request_task', N'P') IS NOT NULL
    DROP PROCEDURE wf.sp_worker_request_task;
IF OBJECT_ID(N'wf.wf_worker_capability_allowed', N'FN') IS NOT NULL
    DROP FUNCTION wf.wf_worker_capability_allowed;
IF OBJECT_ID(N'wf.wf_worker_is_omnibus', N'FN') IS NOT NULL
    DROP FUNCTION wf.wf_worker_is_omnibus;
GO

CREATE FUNCTION wf.wf_worker_is_omnibus(@capabilities json)
RETURNS BIT
AS
BEGIN
    -- Only explicit ["*"] is omnibus. NULL / [] mean "no capabilities".
    IF @capabilities IS NULL
        RETURN 0;
    IF NOT EXISTS (SELECT 1 FROM OPENJSON(@capabilities))
        RETURN 0;
    IF EXISTS (
        SELECT 1
        FROM OPENJSON(@capabilities) WITH (value NVARCHAR(128) '$') AS caps
        WHERE caps.value = N'*'
    )
        RETURN 1;
    RETURN 0;
END;
GO

CREATE FUNCTION wf.wf_worker_capability_allowed(
    @worker_capabilities json,
    @task_capability NVARCHAR(128)
)
RETURNS BIT
AS
BEGIN
    IF @task_capability IS NULL
        RETURN 1;
    IF wf.wf_worker_is_omnibus(@worker_capabilities) = 1
        RETURN 1;
    IF EXISTS (
        SELECT 1
        FROM OPENJSON(@worker_capabilities) WITH (value NVARCHAR(128) '$') AS caps
        WHERE caps.value = @task_capability
    )
        RETURN 1;
    RETURN 0;
END;
GO

CREATE OR ALTER PROCEDURE wf.sp_worker_request_task
    @worker_id BIGINT,
    @worker_token NVARCHAR(4000),
    @capability NVARCHAR(128) NULL,
    @max_lease_seconds INT = 300
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    EXEC wf.wf_worker_authenticate @worker_id = @worker_id, @worker_token = @worker_token;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @lease_end DATETIME2(7) = DATEADD(SECOND, @max_lease_seconds, @now);
    DECLARE @worker_capabilities json;
    DECLARE @is_omnibus BIT;
    DECLARE @reclaim_cutoff DATETIME2(7) = DATEADD(SECOND, -60, @now);

    -- Auto-unstick crashed workers: expired/missing leases → READY (quiet: no result set).
    IF EXISTS (
        SELECT 1
        FROM wf.node_execution AS ne
        LEFT JOIN wf.task_lease AS l ON l.node_execution_id = ne.id
        WHERE ne.status = N'RUNNING'
          AND (
                l.node_execution_id IS NULL
             OR l.lease_expires_at_utc <= @reclaim_cutoff
          )
    )
    BEGIN
        EXEC wf.sp_reclaim_expired_leases @grace_seconds = 60, @quiet = 1;
    END

    SELECT @worker_capabilities = w.capabilities
    FROM wf.worker AS w
    WHERE w.id = @worker_id;

    SET @is_omnibus = wf.wf_worker_is_omnibus(@worker_capabilities);

    IF @capability IS NOT NULL
       AND @is_omnibus = 0
       AND wf.wf_worker_capability_allowed(@worker_capabilities, @capability) = 0
    BEGIN
        RETURN;
    END

    BEGIN TRANSACTION;

    DECLARE @picked_ids TABLE (id BIGINT);

    ;WITH cte AS (
        SELECT TOP (1) ne.id
        FROM wf.node_execution AS ne WITH (ROWLOCK, READPAST, UPDLOCK)
        INNER JOIN wf.workflow_node AS wn ON wn.id = ne.workflow_node_id
        INNER JOIN wf.workflow_action AS wa ON wa.id = wn.workflow_action_id
        INNER JOIN wf.workflow_instance AS wi ON wi.id = ne.workflow_instance_id
        WHERE ne.status = N'READY'
          AND ne.input_json IS NOT NULL
          AND wn.node_type = N'ACTION'
          AND wi.status = N'RUNNING'
          AND (ne.available_at_utc IS NULL OR ne.available_at_utc <= @now)
          AND wf.wf_worker_capability_allowed(@worker_capabilities, wa.capability) = 1
          AND (
              @capability IS NULL
              OR wa.capability = @capability
              OR wa.capability IS NULL
          )
        ORDER BY ne.available_at_utc ASC, ne.id ASC
    )
    UPDATE ne
    SET status = N'RUNNING',
        started_at_utc = @now
    OUTPUT inserted.id INTO @picked_ids(id)
    FROM wf.node_execution AS ne
    INNER JOIN cte ON cte.id = ne.id;

    DECLARE @picked BIGINT;
    SELECT @picked = id FROM @picked_ids;

    IF @picked IS NULL
    BEGIN
        ROLLBACK TRANSACTION;
        RETURN;
    END

    ;MERGE wf.task_lease AS t
    USING (SELECT @picked AS node_execution_id) AS s ON (t.node_execution_id = s.node_execution_id)
    WHEN MATCHED THEN
        UPDATE SET worker_id = @worker_id, lease_expires_at_utc = @lease_end, heartbeat_at_utc = @now
    WHEN NOT MATCHED THEN
        INSERT (node_execution_id, worker_id, lease_expires_at_utc, heartbeat_at_utc)
        VALUES (@picked, @worker_id, @lease_end, @now);

    COMMIT TRANSACTION;

    SELECT
        ne.id AS node_execution_id,
        ne.workflow_instance_id,
        wn.node_key,
        wa.action_name,
        wa.capability,
        ne.attempt_no,
        ne.input_json,
        ne.iteration_no
    FROM wf.node_execution AS ne
    INNER JOIN wf.workflow_node AS wn ON wn.id = ne.workflow_node_id
    INNER JOIN wf.workflow_action AS wa ON wa.id = wn.workflow_action_id
    WHERE ne.id = @picked;
END;
GO

--
-- Create or alter procedure [wf].[sp_worker_heartbeat]
--
GO
PRINT (N'Create or alter procedure [wf].[sp_worker_heartbeat]')
GO

CREATE OR ALTER PROCEDURE wf.sp_worker_heartbeat
    @node_execution_id BIGINT,
    @worker_id BIGINT,
    @worker_token NVARCHAR(4000),
    @extend_seconds INT = 300
AS
BEGIN
    SET NOCOUNT ON;

    EXEC wf.wf_worker_authenticate @worker_id = @worker_id, @worker_token = @worker_token;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();

    UPDATE tl
    SET lease_expires_at_utc = DATEADD(SECOND, @extend_seconds, @now),
        heartbeat_at_utc = @now
    FROM wf.task_lease AS tl
    WHERE tl.node_execution_id = @node_execution_id AND tl.worker_id = @worker_id;

    SELECT @@ROWCOUNT AS rows_updated;
END;
GO

--
-- Create or alter procedure [wf].[sp_worker_fail_task]
--
GO
PRINT (N'Create or alter procedure [wf].[sp_worker_fail_task]')
GO

CREATE OR ALTER PROCEDURE wf.sp_worker_fail_task
    @node_execution_id BIGINT,
    @worker_id BIGINT,
    @worker_token NVARCHAR(4000),
    @error_code INT,
    @error_message NVARCHAR(1024) NULL
AS
BEGIN
    SET NOCOUNT ON;

    EXEC wf.wf_worker_authenticate @worker_id = @worker_id, @worker_token = @worker_token;

    IF NOT EXISTS (
        SELECT 1 FROM wf.task_lease WHERE node_execution_id = @node_execution_id AND worker_id = @worker_id
    )
        RETURN;

    UPDATE wf.node_execution
    SET status = N'FAILED',
        engine_error_code = @error_code,
        engine_error_message = @error_message,
        ended_at_utc = SYSUTCDATETIME()
    WHERE id = @node_execution_id AND status = N'RUNNING';

    DELETE FROM wf.task_lease WHERE node_execution_id = @node_execution_id;

    -- Do not mark workflow_instance FAILED here: one sample action failure must not
    -- strand sibling READY tasks in a FOREACH (SamplePrep Align fan-out).
END;
GO

--
-- Create or alter procedure [wf].[sp_reclaim_expired_leases]
-- See also: wf_reclaim_expired_leases.sql (portal wrapper).
--
GO
PRINT (N'Create or alter procedure [wf].[sp_reclaim_expired_leases]')
GO

CREATE OR ALTER PROCEDURE wf.sp_reclaim_expired_leases
    @workflow_instance_id BIGINT = NULL,
    @grace_seconds INT = 60,
    @quiet BIT = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @grace_seconds < 0 SET @grace_seconds = 0;

    DECLARE @cutoff DATETIME2(7) = DATEADD(SECOND, -@grace_seconds, SYSUTCDATETIME());
    DECLARE @reclaimed TABLE (
        node_execution_id BIGINT NOT NULL,
        workflow_instance_id BIGINT NOT NULL,
        previous_worker_id BIGINT NULL,
        lease_expired_at_utc DATETIME2(7) NULL
    );

    BEGIN TRANSACTION;

    ;WITH expired AS (
        SELECT ne.id AS node_execution_id,
               ne.workflow_instance_id,
               l.worker_id AS previous_worker_id,
               l.lease_expires_at_utc
        FROM wf.node_execution AS ne
        LEFT JOIN wf.task_lease AS l ON l.node_execution_id = ne.id
        WHERE ne.status = N'RUNNING'
          AND (
                l.node_execution_id IS NULL
             OR l.lease_expires_at_utc <= @cutoff
          )
          AND (@workflow_instance_id IS NULL OR ne.workflow_instance_id = @workflow_instance_id)
    )
    UPDATE ne
    SET status = N'READY',
        result_code = NULL,
        engine_error_code = NULL,
        engine_error_message = N'reclaimed: lease expired or missing',
        output_json = NULL,
        started_at_utc = NULL,
        ended_at_utc = NULL,
        attempt_no = ISNULL(ne.attempt_no, 0) + 1,
        available_at_utc = SYSUTCDATETIME()
    OUTPUT inserted.id, inserted.workflow_instance_id, e.previous_worker_id, e.lease_expires_at_utc
    INTO @reclaimed (node_execution_id, workflow_instance_id, previous_worker_id, lease_expired_at_utc)
    FROM wf.node_execution AS ne
    INNER JOIN expired AS e ON e.node_execution_id = ne.id
    WHERE ne.status = N'RUNNING';

    DELETE l
    FROM wf.task_lease AS l
    INNER JOIN @reclaimed AS r ON r.node_execution_id = l.node_execution_id;

    COMMIT TRANSACTION;

    IF @quiet = 0
    BEGIN
        SELECT node_execution_id,
               workflow_instance_id,
               previous_worker_id,
               lease_expired_at_utc,
               SYSUTCDATETIME() AS reclaimed_at_utc
        FROM @reclaimed
        ORDER BY node_execution_id;
    END
END;
GO

