--
-- Create or alter procedure [RBAC].[spGetUserIdByEmail]
--
GO
PRINT (N'Create or alter procedure [RBAC].[spGetUserIdByEmail]')
GO
/* 
	Author	Inty Saez 
	Date 	04/13/2026
	Subject	Get UserId by User's email  
*/

CREATE OR ALTER PROCEDURE RBAC.spGetUserIdByEmail
    @Email  NVARCHAR(100),
    @UserId INT = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT @UserId = u.ID
    FROM   RBAC.Users u
    WHERE  u.email = @Email
      AND  u.Active = 1;
    -- Returns NULL in @UserId if no active user found.
END;
GO

