--
-- Create or alter procedure [RBAC].[spGetUserRoles]
--
GO
PRINT (N'Create or alter procedure [RBAC].[spGetUserRoles]')
GO

/*
	Author	Inty Saez 
	Date 	04/13/2026
	Subject Get User's Role 
*/


CREATE OR ALTER PROCEDURE RBAC.spGetUserRoles
    @UserId INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT DISTINCT
        @UserId     AS UserId,
        r.Name      AS Role,
        r.ID        AS RoleId
    FROM   RBAC.Group_Users  gu
    JOIN   RBAC.Group_Roles  gr  ON gr.GroupID = gu.GroupID
    JOIN   RBAC.Roles        r   ON r.ID       = gr.RoleID
    WHERE  gu.UserID = @UserId
    ORDER BY r.Name;
END;
GO

